sp_widget.client_script:
api.controller = function($scope, spModal) {

    var c = this;

    c.processingApproval = {};
    c.actionMessage = "";
    c.actionSuccess = false;


    c.approveLeave = function(leave) {

        if (!leave || !leave.sys_id) {
            return;
        }

        spModal.confirm(
            "Approve Leave Request " +
            leave.number +
            " for " +
            leave.employee +
            "?"
        ).then(function(confirmed) {

            if (!confirmed) {
                return;
            }

            submitApproval(
                leave,
                "approve_leave",
                ""
            );

        });

    };


    c.rejectLeave = function(leave) {

        if (!leave || !leave.sys_id) {
            return;
        }

        spModal.prompt(
            "Enter the reason for rejecting " +
            leave.number +
            ":"
        ).then(function(reason) {

            reason = (reason || "").trim();

            if (!reason) {

                c.actionSuccess = false;
                c.actionMessage =
                    "A rejection reason is required.";

                return;
            }

            spModal.confirm(
                "Reject Leave Request " +
                leave.number +
                "?"
            ).then(function(confirmed) {

                if (!confirmed) {
                    return;
                }

                submitApproval(
                    leave,
                    "reject_leave",
                    reason
                );

            });

        });

    };


    function submitApproval(
        leave,
        action,
        comments
    ) {

        if (
            c.processingApproval[
                leave.sys_id
            ]
        ) {
            return;
        }

        c.processingApproval[
            leave.sys_id
        ] = true;

        c.actionMessage = "";


        c.server.get({

            action: action,
            leave_sys_id: leave.sys_id,
            comments: comments || ""

        }).then(function(response) {

            c.processingApproval[
                leave.sys_id
            ] = false;


            var result =
                response &&
                response.data
                ? response.data.actionResult
                : null;


            if (!result) {

                c.actionSuccess = false;

                c.actionMessage =
                    "The approval response could not be processed.";

                return;
            }


            c.actionSuccess =
                result.success === true;


            c.actionMessage =
                result.message ||
                (
                    result.success
                    ? "Approval processed successfully."
                    : "Approval could not be processed."
                );


            if (result.success) {

                removeProcessedLeave(
                    leave.sys_id
                );

                setTimeout(function() {

                    c.server.refresh();

                }, 1200);

            }

        }, function() {

            c.processingApproval[
                leave.sys_id
            ] = false;

            c.actionSuccess = false;

            c.actionMessage =
                "An unexpected error occurred while processing the Leave Request.";

        });

    }


    function removeProcessedLeave(
        leaveSysId
    ) {

        if (
            !c.data ||
            !c.data.recentLeaveRequests
        ) {
            return;
        }


        for (
            var i =
                c.data.recentLeaveRequests.length - 1;
            i >= 0;
            i--
        ) {

            if (
                c.data.recentLeaveRequests[i].sys_id ==
                leaveSysId
            ) {

                c.data.recentLeaveRequests.splice(
                    i,
                    1
                );

            }

        }


        if (
            c.data.pendingHRApprovals > 0
        ) {

            c.data.pendingHRApprovals--;

        }

    }

};

sp_widget.css:
/* =========================================================
   PAGE
========================================================= */

.uhr-dashboard {
  display: flex;
  width: 100vw;
  min-height: 100vh;
  margin-left: calc(50% - 50vw);
  background: #f7f9fc;
  font-family: Arial, sans-serif;
  color: #12204b;
  box-sizing: border-box;
}

.uhr-dashboard *,
.uhr-dashboard *:before,
.uhr-dashboard *:after {
  box-sizing: border-box;
}


/* =========================================================
   SIDEBAR
========================================================= */

.hr-sidebar {
  width: 245px;
  min-width: 245px;
  min-height: 100vh;
  padding: 18px 14px;
  background: #062f3d;
  color: #ffffff;
  display: flex;
  flex-direction: column;
  box-shadow: 2px 0 8px rgba(0,0,0,.08);
}

.hr-brand {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 4px 10px 18px;
  border-bottom: 1px solid rgba(255,255,255,.13);
}

.hr-logo {
  width: 42px;
  height: 42px;
  min-width: 42px;
  border-radius: 10px;
  background: #ffffff;
  color: #114b95;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 19px;
  font-weight: 800;
}

.hr-brand-title {
  font-size: 16px;
  font-weight: 700;
  color: #ffffff;
}

.hr-brand-sub {
  margin-top: 3px;
  font-size: 11px;
  color: #b7d2d9;
}


/* USER */

.hr-sidebar-user {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 16px 10px 12px;
}

.hr-sidebar-avatar {
  width: 38px;
  height: 38px;
  min-width: 38px;
  border-radius: 50%;
  background: #2b7d8d;
  color: white;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
}

.hr-sidebar-user strong {
  display: block;
  font-size: 12px;
  color: white;
}

.hr-sidebar-user small {
  display: block;
  margin-top: 3px;
  font-size: 10px;
  color: #b9d0d6;
}


/* NAV */

.hr-nav {
  flex: 1;
}

.hr-nav-heading {
  padding: 14px 10px 6px;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  color: #a6c4cc;
  letter-spacing: .4px;
}

.hr-nav-item {
  min-height: 42px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 11px;
  margin: 2px 0;
  border-radius: 6px;
  color: #eff8fa !important;
  text-decoration: none !important;
  font-size: 12px;
}

.hr-nav-item:hover {
  background: rgba(255,255,255,.10);
  color: #ffffff !important;
}

.hr-nav-item.active {
  background: #164a5b;
  box-shadow: inset 3px 0 0 #81d742;
  color: #ffffff !important;
  font-weight: 600;
}

.hr-nav-count {
  margin-left: auto;
  min-width: 21px;
  height: 21px;
  padding: 0 6px;
  border-radius: 11px;
  background: #81d742;
  color: #062f3d;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 700;
}

.hr-nav-count.warning {
  background: #25c89e;
  color: white;
}

.notification-count {
  background: #ef4444 !important;
  color: #ffffff !important;
}


/* =========================================================
   MAIN
========================================================= */

.hr-main {
  flex: 1;
  min-width: 0;
  padding: 28px 30px 40px;
  background: #f8faff;
}


/* TOP BAR */

.hr-topbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 22px;
  gap: 20px;
}

.hr-topbar h1 {
  margin: 0 0 6px;
  font-size: 26px;
  font-weight: 700;
  color: #0f2360;
}

.hr-topbar p {
  margin: 0;
  font-size: 13px;
  color: #6f7890;
}

.hr-profile {
  display: flex;
  align-items: center;
  gap: 10px;
  background: white;
  padding: 8px 12px;
  border-radius: 10px;
  border: 1px solid #edf0f5;
}

.hr-top-avatar {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: #edf3ff;
  color: #3757ae;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
}

.hr-profile strong {
  display: block;
  font-size: 12px;
  color: #152457;
}

.hr-profile small {
  display: block;
  margin-top: 2px;
  font-size: 10px;
  color: #7e879d;
}


/* =========================================================
   MESSAGES
========================================================= */

.dashboard-message {
  padding: 13px 16px;
  margin-bottom: 18px;
  border-radius: 9px;
  font-size: 12px;
  font-weight: 600;
}

.dashboard-message.success {
  background: #ecfdf5;
  border: 1px solid #a7f3d0;
  color: #047857;
}

.dashboard-message.error {
  background: #fef2f2;
  border: 1px solid #fecaca;
  color: #b91c1c;
}


/* =========================================================
   KPI CARDS
========================================================= */

.hr-stats-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 14px;
  width: 100%;
  margin-bottom: 18px;
  align-items: stretch;
}

.hr-stat-card {
  position: relative;
  min-height: 190px;
  min-width: 0;
  padding: 20px;
  border: 1px solid #e2e7ef;
  border-radius: 12px;
  background: white;
  box-shadow: 0 3px 12px rgba(20,40,90,.04);
  transition: .2s;
}

.hr-stat-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 7px 18px rgba(20,40,90,.08);
}

.hr-stat-icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 14px;
  font-size: 21px;
}

.hr-stat-icon.purple {
  background: #eee8ff;
  color: #6948d7;
}

.hr-stat-icon.orange {
  background: #fff0d8;
  color: #ed9416;
}

.hr-stat-icon.blue {
  background: #e5efff;
  color: #3478e5;
}

.hr-stat-icon.green {
  background: #e3f6e8;
  color: #169d52;
}

.hr-stat-icon.pink {
  background: #fde7ef;
  color: #db2777;
}

.leaves-card {
  border-color: #f4c7d8;
  background: #fffafb;
}

.hr-stat-title {
  margin-bottom: 7px;
  font-size: 13px;
  font-weight: 700;
  color: #17234e;
}

.hr-stat-value {
  margin-bottom: 4px;
  font-size: 30px;
  font-weight: 700;
  color: #0f1f50;
}

.hr-stat-sub {
  min-height: 31px;
  margin-bottom: 12px;
  font-size: 11px;
  line-height: 1.5;
  color: #69738b;
}

.hr-stat-card a {
  color: #4167d9;
  font-size: 11px;
  font-weight: 600;
  text-decoration: none;
}


/* =========================================================
   ANALYTICS
========================================================= */

.hr-analytics-grid {
  display: grid;
  grid-template-columns: 1.15fr 1fr 1.25fr;
  gap: 16px;
  margin-bottom: 18px;
}

.analytics-card {
  min-height: 285px;
  padding: 18px;
  background: #ffffff;
  border: 1px solid #e2e7ef;
  border-radius: 14px;
  box-shadow: 0 3px 12px rgba(15,27,69,.04);
}

.analytics-header {
  margin-bottom: 18px;
}

.analytics-header h3 {
  margin: 0;
  color: #0f1b45;
  font-size: 15px;
  font-weight: 700;
}

.donut-layout {
  min-height: 190px;
  display: flex;
  align-items: center;
  gap: 22px;
}

.donut-chart {
  width: 145px;
  height: 145px;
  min-width: 145px;
  border-radius: 50%;
  position: relative;
}

.donut-chart:after {
  content: "";
  position: absolute;
  inset: 29px;
  background: #ffffff;
  border-radius: 50%;
}

.donut-center {
  position: absolute;
  z-index: 2;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.donut-center span {
  color: #64748b;
  font-size: 10px;
}

.donut-center strong {
  margin-top: 2px;
  color: #0f1b45;
  font-size: 19px;
}

.chart-legend {
  flex: 1;
}

.chart-legend > div {
  display: grid;
  grid-template-columns: 10px 1fr auto;
  gap: 7px;
  align-items: center;
  margin-bottom: 11px;
  color: #43506a;
  font-size: 10px;
}

.chart-legend strong {
  color: #172554;
}

.legend-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

.hod-dot {
  background: #f59e0b;
}

.hr-dot {
  background: #3b82f6;
}

.approved-dot {
  background: #22c55e;
}

.rejected-dot {
  background: #ef4444;
}

.cancelled-dot {
  background: #a855f7;
}

.case-open-dot {
  background: #f59e0b;
}

.case-progress-dot {
  background: #3b82f6;
}

.case-resolved-dot {
  background: #22c55e;
}

.case-closed-dot {
  background: #6b7280;
}


/* CATEGORY CHART */

.category-chart {
  padding-top: 4px;
  min-height: 190px;
}

.category-row {
  display: grid;
  grid-template-columns: 105px 1fr 25px;
  gap: 10px;
  align-items: center;
  margin-bottom: 19px;
}

.category-name {
  color: #36425e;
  font-size: 10px;
}

.category-bar-track {
  height: 6px;
  overflow: hidden;
  background: #eef2f7;
  border-radius: 10px;
}

.category-bar {
  height: 100%;
  min-width: 4px;
  border-radius: 10px;
  background: #6d5dfc;
}

.category-count {
  color: #172554;
  font-size: 10px;
  text-align: right;
}

.empty-analytics {
  padding: 60px 10px;
  text-align: center;
  color: #94a3b8;
  font-size: 11px;
}


/* =========================================================
   ROLE BANNERS
========================================================= */

.hr-manager-banner,
.hr-agent-banner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 15px 18px;
  margin-bottom: 18px;
  border-radius: 11px;
  background: white;
  border: 1px solid #e0e5ef;
}

.hr-manager-banner {
  border-left: 4px solid #6947dc;
}

.hr-agent-banner {
  border-left: 4px solid #3481e7;
}

.hr-manager-banner h3,
.hr-agent-banner h3 {
  margin: 0 0 4px;
  font-size: 15px;
  color: #132052;
}

.hr-manager-banner p,
.hr-agent-banner p {
  margin: 0;
  font-size: 11px;
  color: #7b8499;
}

.agent-label {
  display: block;
  margin-bottom: 4px;
  color: #64748b;
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
}

.manager-badge,
.agent-badge {
  padding: 6px 11px;
  border-radius: 14px;
  font-size: 10px;
  font-weight: 700;
}

.manager-badge {
  background: #eee8ff;
  color: #5d40c8;
}

.agent-badge {
  background: #e9f2ff;
  color: #3270cc;
}


/* =========================================================
   PANELS
========================================================= */

.hr-panel {
  padding: 18px;
  margin-bottom: 18px;
  background: #ffffff;
  border: 1px solid #e2e7ef;
  border-radius: 12px;
  box-shadow: 0 3px 10px rgba(30,50,90,.04);
}

.hr-panel-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 15px;
  margin-bottom: 14px;
}

.hr-panel-header h3 {
  margin: 0;
  font-size: 15px;
  color: #172250;
}

.hr-panel-header p {
  margin: 4px 0 0;
  font-size: 10px;
  line-height: 1.5;
  color: #7d869a;
}

.hr-panel-header a {
  color: #2665d8;
  text-decoration: none;
  font-size: 11px;
}


/* =========================================================
   TABLES
========================================================= */

.hr-table-wrap {
  width: 100%;
  overflow-x: auto;
}

.hr-table {
  width: 100%;
  border-collapse: collapse;
}

.hr-table th {
  padding: 10px;
  background: #f6f8fb;
  border-bottom: 1px solid #e9edf3;
  text-align: left;
  white-space: nowrap;
  font-size: 10px;
  color: #36405d;
}

.hr-table td {
  padding: 11px 10px;
  border-bottom: 1px solid #eef1f5;
  vertical-align: middle;
  font-size: 11px;
  color: #273451;
}

.hr-table tr:last-child td {
  border-bottom: none;
}

.hr-table tbody tr:hover {
  background: #fbfcff;
}

.case-link {
  color: #1769e0;
  text-decoration: none;
}

.case-link:hover {
  text-decoration: underline;
}

.empty-row {
  padding: 28px !important;
  text-align: center !important;
  color: #919aad !important;
}

.unassigned {
  color: #9ca3b3;
  font-style: italic;
}


/* =========================================================
   PILLS
========================================================= */

.priority-pill,
.case-status,
.leave-pending {
  display: inline-block;
  padding: 5px 9px;
  border-radius: 14px;
  white-space: nowrap;
  font-size: 9px;
  font-weight: 600;
}

.priority-high,
.priority-critical {
  background: #ffe7e6;
  color: #d43a33;
}

.priority-medium {
  background: #fff1d7;
  color: #d77c00;
}

.priority-low {
  background: #e3f5e9;
  color: #1e8b5e;
}

.case-open {
  background: #fff0da;
  color: #cc7500;
}

.case-progress {
  background: #e5efff;
  color: #2d70d7;
}

.case-resolved {
  background: #e2f6eb;
  color: #11865a;
}

.case-closed {
  background: #edf0f4;
  color: #5e687c;
}

.leave-pending {
  background: #fff0d8;
  color: #cd7700;
}


/* =========================================================
   LEAVE APPROVAL PANEL
========================================================= */

.leave-approval-panel {
  border-top: 3px solid #25a77d;
}

.pending-total {
  padding: 7px 12px;
  border-radius: 18px;
  background: #fff4db;
  color: #b56500;
  font-size: 10px;
  font-weight: 700;
  white-space: nowrap;
}

.approval-info-banner {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 13px 15px;
  margin-bottom: 15px;
  border: 1px solid #cde9ff;
  border-radius: 9px;
  background: #f3f9ff;
}

.approval-info-icon {
  width: 25px;
  height: 25px;
  min-width: 25px;
  border-radius: 50%;
  background: #dbeeff;
  color: #1769e0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
}

.approval-info-banner strong {
  color: #164e78;
  font-size: 11px;
}

.approval-info-banner p {
  margin: 3px 0 0;
  color: #64748b;
  font-size: 10px;
  line-height: 1.5;
}

.leave-approval-table {
  min-width: 1050px;
}

.leave-actions-cell {
  min-width: 170px;
}

.leave-action-buttons {
  display: flex;
  gap: 6px;
}

.leave-btn {
  min-width: 72px;
  padding: 7px 9px;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  font-size: 9px;
  font-weight: 700;
  transition: .15s;
}

.leave-btn.approve {
  background: #dcfce7;
  color: #15803d;
  border: 1px solid #bbf7d0;
}

.leave-btn.approve:hover:not(:disabled) {
  background: #bbf7d0;
}

.leave-btn.reject {
  background: #fee2e2;
  color: #b91c1c;
  border: 1px solid #fecaca;
}

.leave-btn.reject:hover:not(:disabled) {
  background: #fecaca;
}

.leave-btn:disabled {
  cursor: not-allowed;
  opacity: .55;
}

.review-only-link {
  color: #1769e0;
  font-size: 10px;
  font-weight: 600;
  text-decoration: none;
}

.review-only-link:hover {
  text-decoration: underline;
}

.not-your-approval {
  margin-top: 3px;
  max-width: 130px;
  color: #94a3b8;
  font-size: 8px;
  line-height: 1.3;
}

.leave-table-footer {
  padding-top: 11px;
  text-align: right;
  color: #94a3b8;
  font-size: 9px;
}


/* =========================================================
   QUICK ACTIONS
========================================================= */

.hr-quick-grid {
  display: grid;
  grid-template-columns: repeat(6, minmax(0,1fr));
  gap: 10px;
}

.hr-quick-grid a {
  min-height: 105px;
  padding: 13px 8px;
  border: 1px solid #e4e8ef;
  border-radius: 10px;
  background: #ffffff;
  color: #17234f;
  text-decoration: none !important;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  transition: .2s;
}

.hr-quick-grid a:hover {
  background: #f8faff;
  transform: translateY(-2px);
}

.quick-action-icon {
  margin-bottom: 8px;
  font-size: 27px;
}

.hr-quick-grid strong {
  font-size: 10px;
}


/* =========================================================
   RESPONSIVE
========================================================= */

@media (max-width: 1250px) {

  .hr-stats-grid {
    grid-template-columns: repeat(3, minmax(0,1fr));
  }

  .hr-analytics-grid {
    grid-template-columns: 1fr;
  }

  .hr-quick-grid {
    grid-template-columns: repeat(3, minmax(0,1fr));
  }

}


@media (max-width: 900px) {

  .uhr-dashboard {
    display: block;
    width: 100%;
    margin-left: 0;
  }

  .hr-sidebar {
    width: 100%;
    min-width: 0;
    min-height: auto;
  }

  .hr-main {
    padding: 22px 18px 35px;
  }

  .hr-topbar {
    align-items: flex-start;
    flex-direction: column;
  }

  .hr-stats-grid {
    grid-template-columns: repeat(2, minmax(0,1fr));
  }

  .donut-layout {
    align-items: flex-start;
    flex-direction: column;
  }

}


@media (max-width: 600px) {

  .hr-stats-grid,
  .hr-quick-grid {
    grid-template-columns: 1fr;
  }

  .hr-topbar h1 {
    font-size: 22px;
  }

  .hr-manager-banner,
  .hr-agent-banner {
    align-items: flex-start;
    flex-direction: column;
    gap: 12px;
  }

}

/* =========================================================
   EXECUTIVE HR INSIGHTS
   HR MANAGER ONLY
========================================================= */

.executive-insights-section {
  margin-bottom: 22px;
}

.executive-insights-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 20px;

  padding: 18px 20px;
  margin-bottom: 14px;

  background:
    linear-gradient(
      135deg,
      #10245f,
      #244b91
    );

  border-radius: 14px;
}

.executive-label {
  display: block;

  margin-bottom: 6px;

  color: #acd0ff;

  font-size: 9px;
  font-weight: 700;

  letter-spacing: 1px;
}

.executive-insights-header h2 {
  margin: 0 0 5px;

  color: #ffffff;

  font-size: 18px;
  font-weight: 700;
}

.executive-insights-header p {
  margin: 0;

  max-width: 700px;

  color: #d7e4fb;

  font-size: 10px;
  line-height: 1.55;
}

.executive-badge {
  padding: 6px 11px;

  background: rgba(255,255,255,.14);

  border: 1px solid rgba(255,255,255,.22);

  border-radius: 18px;

  color: #ffffff;

  font-size: 9px;
  font-weight: 700;

  white-space: nowrap;
}


/* GRID */

.executive-insight-grid {
  display: grid;

  grid-template-columns:
    minmax(0, 1.65fr)
    minmax(280px, .75fr);

  gap: 16px;
}


/* CARD */

.executive-insight-card {
  padding: 20px;

  background: #ffffff;

  border: 1px solid #e1e7f0;

  border-radius: 14px;

  box-shadow:
    0 4px 14px rgba(15,35,80,.05);
}

.executive-card-header {
  display: flex;

  justify-content: space-between;
  align-items: flex-start;

  gap: 15px;

  margin-bottom: 18px;
}

.executive-card-title-row {
  display: flex;

  align-items: center;

  gap: 11px;
}

.executive-card-icon {
  width: 42px;
  height: 42px;

  min-width: 42px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 10px;

  font-size: 18px;
}

.leave-demand-icon {
  background: #eef2ff;
}

.intelligence-icon {
  background: #ecfdf5;

  color: #059669;

  font-size: 20px;
}

.executive-card-header h3 {
  margin: 0 0 4px;

  color: #152457;

  font-size: 14px;
  font-weight: 700;
}

.executive-card-header p {
  margin: 0;

  color: #8290a5;

  font-size: 9px;
  line-height: 1.5;
}

.insight-tag {
  padding: 5px 9px;

  border-radius: 15px;

  background: #edf3ff;

  color: #3762c9;

  font-size: 8px;
  font-weight: 700;

  white-space: nowrap;
}


/* SUMMARY */

.seasonal-summary {
  display: flex;

  align-items: center;

  gap: 25px;

  padding: 12px 15px;

  margin-bottom: 22px;

  background: #f8faff;

  border: 1px solid #edf1f7;

  border-radius: 10px;
}

.seasonal-summary-item span {
  display: block;

  margin-bottom: 4px;

  color: #8490a5;

  font-size: 8px;
}

.seasonal-summary-item strong {
  display: block;

  color: #172554;

  font-size: 17px;
}

.seasonal-summary-item small {
  display: block;

  margin-top: 2px;

  color: #94a3b8;

  font-size: 8px;
}

.seasonal-summary-divider {
  width: 1px;
  height: 42px;

  background: #dde4ee;
}


/* CHART */

.seasonal-chart {
  height: 190px;

  display: grid;

  grid-template-columns:
    repeat(6, minmax(0,1fr));

  gap: 14px;

  align-items: end;

  padding: 10px 8px 0;
}

.seasonal-column {
  height: 100%;

  display: flex;

  flex-direction: column;

  align-items: center;

  justify-content: flex-end;
}

.seasonal-value {
  min-height: 17px;

  margin-bottom: 5px;

  color: #44506a;

  font-size: 8px;
  font-weight: 700;
}

.seasonal-bar-area {
  width: 34px;

  height: 130px;

  display: flex;

  align-items: flex-end;

  overflow: hidden;

  border-radius: 6px 6px 2px 2px;

  background: #f0f3f8;
}

.seasonal-bar {
  width: 100%;

  min-height: 3px;

  border-radius: 6px 6px 2px 2px;

  background:
    linear-gradient(
      180deg,
      #6e7ff2,
      #315fc9
    );

  transition: height .3s ease;
}

.seasonal-month {
  margin-top: 7px;

  color: #657188;

  font-size: 8px;
  font-weight: 600;
}


/* INSIGHT */

.executive-insight-message {
  display: flex;

  align-items: flex-start;

  gap: 10px;

  margin-top: 18px;

  padding: 12px 14px;

  border: 1px solid #c7dcff;

  border-radius: 9px;

  background: #f3f7ff;
}

.insight-message-icon {
  width: 24px;
  height: 24px;

  min-width: 24px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 50%;

  background: #dce8ff;

  color: #315fc9;

  font-size: 12px;
}

.executive-insight-message strong {
  color: #244f9d;

  font-size: 9px;
}

.executive-insight-message p {
  margin: 3px 0 0;

  color: #5f6b80;

  font-size: 9px;

  line-height: 1.55;
}

.executive-empty {
  margin-top: 15px;

  padding: 15px;

  text-align: center;

  border-radius: 8px;

  background: #f8fafc;

  color: #94a3b8;

  font-size: 9px;
}


/* UPCOMING */

.future-insight-list {
  display: flex;

  flex-direction: column;

  gap: 10px;
}

.future-insight-item {
  display: grid;

  grid-template-columns:
    36px 1fr auto;

  gap: 10px;

  align-items: center;

  padding: 12px;

  border: 1px solid #e6eaf0;

  border-radius: 9px;

  background: #fbfcff;
}

.future-insight-icon {
  width: 34px;
  height: 34px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 8px;

  background: #eef2ff;

  font-size: 15px;
}

.future-insight-item strong {
  display: block;

  margin-bottom: 3px;

  color: #172554;

  font-size: 9px;
}

.future-insight-item span {
  display: block;

  color: #8490a5;

  font-size: 8px;

  line-height: 1.45;
}

.coming-badge {
  padding: 4px 7px !important;

  border-radius: 12px;

  background: #eef2ff;

  color: #5268c9 !important;

  font-size: 7px !important;
  font-weight: 700;
}


/* RESPONSIVE */

@media (max-width: 1150px) {

  .executive-insight-grid {
    grid-template-columns: 1fr;
  }

}

@media (max-width: 700px) {

  .executive-insights-header {
    flex-direction: column;
  }

  .seasonal-chart {
    gap: 6px;
  }

  .seasonal-bar-area {
    width: 24px;
  }

}

/* =========================================================
   HR CASE TRENDS - EXECUTIVE INSIGHTS
========================================================= */

.case-trend-live {
  align-items: flex-start;
}

.case-trend-content {
  width: 100%;
  min-width: 0;
}

.case-trend-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 3px;
}

.trend-direction {
  padding: 4px 7px;
  border-radius: 12px;
  font-size: 7px !important;
  font-weight: 700;
}

.trend-up {
  background: #fee2e2;
  color: #b91c1c !important;
}

.trend-down {
  background: #dcfce7;
  color: #15803d !important;
}

.trend-stable {
  background: #eef2ff;
  color: #4f5fbf !important;
}


/* SUMMARY */

.case-trend-summary {
  display: grid;
  grid-template-columns: repeat(3, minmax(0,1fr));
  gap: 8px;
  margin-top: 12px;
}

.case-trend-summary > div {
  padding: 9px;
  background: #f8faff;
  border: 1px solid #edf1f7;
  border-radius: 7px;
}

.case-trend-summary small {
  display: block;
  margin-bottom: 3px;
  color: #94a3b8;
  font-size: 7px;
}

.case-trend-summary strong {
  color: #172554;
  font-size: 9px;
}


/* MINI CHART */

.case-mini-chart {
  height: 95px;
  display: grid;
  grid-template-columns: repeat(6, minmax(0,1fr));
  gap: 6px;
  align-items: end;
  margin-top: 14px;
}

.case-mini-column {
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
}

.case-mini-value {
  min-height: 12px;
  margin-bottom: 3px;
  color: #475569 !important;
  font-size: 7px !important;
  font-weight: 700;
}

.case-mini-bar-track {
  width: 18px;
  height: 60px;
  display: flex;
  align-items: flex-end;
  overflow: hidden;
  border-radius: 4px 4px 2px 2px;
  background: #eef2f7;
}

.case-mini-bar {
  width: 100%;
  min-height: 2px;
  border-radius: 4px 4px 2px 2px;
  background: linear-gradient(
    180deg,
    #7c83f5,
    #4f5ac8
  );
}

.case-mini-month {
  margin-top: 4px;
  color: #7b879c !important;
  font-size: 7px !important;
}


/* MANAGER INSIGHT */

.case-manager-insight {
  margin-top: 13px;
  padding: 10px 11px;
  background: #f3f7ff;
  border: 1px solid #cbdcff;
  border-radius: 7px;
}

.case-manager-insight > strong {
  color: #315fc9;
  font-size: 8px;
}

.case-manager-insight p {
  margin: 4px 0 0;
  color: #5f6b80;
  font-size: 8px;
  line-height: 1.5;
}

.case-manager-insight p strong {
  display: inline;
  color: #172554;
  font-size: 8px;
}

sp_widget.script:
(function() {

    // ----------------------------------
    // 1. LOGGED-IN USER
    // ----------------------------------

    data.userName = gs.getUserDisplayName();
    data.userId = gs.getUserID();

	// ----------------------------------
	// NOTIFICATIONS
	// ----------------------------------

	data.notificationCount = 0;

    data.initials = "";

    var parts = data.userName.split(" ");

    for (var i = 0; i < parts.length && i < 2; i++) {
        if (parts[i]) {
            data.initials += parts[i].charAt(0).toUpperCase();
        }
    }


    // ----------------------------------
    // 2. HR ROLE / GROUP DETECTION
    // ----------------------------------

    data.isHRManager = false;
    data.isHRAgent = false;
    data.isLeaveAgent = false;

    data.hrRoleLabel = "HR User";
    data.agentGroupNames = [];
    data.agentGroupIds = [];


    var currentUser = gs.getUser();

    // HR Manager
    if (currentUser.isMemberOf('HR Managers')) {

        data.isHRManager = true;
        data.hrRoleLabel = "HR Manager";

    } else {

        // HR Agent groups used in this project
        var allowedGroups = [
            'HR Payroll',
            'HR Benefits',
            'HR Employee Relations',
            'HR General',
            'HR Leave Administration'
        ];


        var memberGR = new GlideRecord('sys_user_grmember');

        memberGR.addQuery('user', data.userId);
        memberGR.addQuery('group.name', 'IN', allowedGroups.join(','));
        memberGR.query();


        while (memberGR.next()) {

            data.isHRAgent = true;

            var groupName =
                memberGR.getDisplayValue('group');

            var groupId =
                memberGR.getValue('group');

            data.agentGroupNames.push(groupName);
            data.agentGroupIds.push(groupId);


            if (groupName == 'HR Leave Administration') {
                data.isLeaveAgent = true;
            }
        }


        if (data.isHRAgent) {

            if (data.agentGroupNames.length == 1) {
                data.hrRoleLabel =
                    data.agentGroupNames[0] + " Agent";
            } else {
                data.hrRoleLabel = "HR Agent";
            }
        }
    }



    // ----------------------------------
    // 3. INITIALIZE DASHBOARD COUNTERS
    // ----------------------------------

    data.pendingHRApprovals = 0;
    data.openCases = 0;
    data.inProgressCases = 0;
    data.resolvedThisMonth = 0;


    // ----------------------------------
    // 4. INITIALIZE ARRAYS
    // ----------------------------------

    data.recentLeaveRequests = [];
    data.recentHRCases = [];



    // ----------------------------------
    // HELPER FUNCTION:
    // APPLY HR CASE FILTER
    // ----------------------------------

    function applyCaseFilter(gr) {

        // Manager sees everything
        if (data.isHRManager) {
            return;
        }


        // Agent sees:
        // cases belonging to their HR group
        // OR explicitly assigned to them
        if (data.isHRAgent &&
            data.agentGroupIds.length > 0) {

            var qc =
                gr.addQuery(
                    'assignment_group',
                    'IN',
                    data.agentGroupIds.join(',')
                );

            qc.addOrCondition(
                'assigned_to',
                data.userId
            );

            return;
        }


        // If user is neither HR Manager nor HR Agent,
        // prevent them from seeing HR cases.
        gr.addQuery('sys_id', 'ISEMPTY');
    }



    // ----------------------------------
    // 5. PENDING HR LEAVE APPROVALS
    // Manager + Leave Agent only
    // ----------------------------------

    if (data.isHRManager || data.isLeaveAgent) {

        var pendingLeaveGA =
            new GlideAggregate(
                'x_snc_unified_hr_0_leave_request'
            );

        pendingLeaveGA.addQuery(
            'status',
            'pending_hr'
        );

        pendingLeaveGA.addAggregate('COUNT');
        pendingLeaveGA.query();

        if (pendingLeaveGA.next()) {

            data.pendingHRApprovals =
                parseInt(
                    pendingLeaveGA.getAggregate('COUNT'),
                    10
                ) || 0;
        }
    }



    // ----------------------------------
    // 6. OPEN HR CASES
    // ----------------------------------

    var openGA =
        new GlideAggregate(
            'x_snc_unified_hr_0_hr_case'
        );

    applyCaseFilter(openGA);

    openGA.addQuery(
        'status',
        'open'
    );

    openGA.addAggregate('COUNT');
    openGA.query();

    if (openGA.next()) {

        data.openCases =
            parseInt(
                openGA.getAggregate('COUNT'),
                10
            ) || 0;
    }



    // ----------------------------------
    // 7. IN PROGRESS HR CASES
    // ----------------------------------

    var progressGA =
        new GlideAggregate(
            'x_snc_unified_hr_0_hr_case'
        );

    applyCaseFilter(progressGA);

    progressGA.addQuery(
        'status',
        'in_progress'
    );

    progressGA.addAggregate('COUNT');
    progressGA.query();

    if (progressGA.next()) {

        data.inProgressCases =
            parseInt(
                progressGA.getAggregate('COUNT'),
                10
            ) || 0;
    }



    // ----------------------------------
    // 8. RESOLVED THIS MONTH
    // ----------------------------------

    var nowGdt = new GlideDateTime();

    var year =
        nowGdt.getYearUTC();

    var month =
        nowGdt.getMonthUTC();

    var monthString =
        month < 10
        ? "0" + month
        : "" + month;


    var startMonth =
        new GlideDateTime(
            year +
            "-" +
            monthString +
            "-01 00:00:00"
        );


    var nextMonth = month + 1;
    var nextYear = year;

    if (nextMonth > 12) {

        nextMonth = 1;
        nextYear = year + 1;
    }


    var nextMonthString =
        nextMonth < 10
        ? "0" + nextMonth
        : "" + nextMonth;


    var startNextMonth =
        new GlideDateTime(
            nextYear +
            "-" +
            nextMonthString +
            "-01 00:00:00"
        );


    var resolvedGA =
        new GlideAggregate(
            'x_snc_unified_hr_0_hr_case'
        );

    applyCaseFilter(resolvedGA);

    resolvedGA.addQuery(
        'status',
        'resolved'
    );

    /*
      Your HR Case table currently does not have
      a dedicated Resolved On field.

      So for the MVP we use sys_updated_on
      to count records resolved/updated this month.
    */

    resolvedGA.addQuery(
        'sys_updated_on',
        '>=',
        startMonth
    );

    resolvedGA.addQuery(
        'sys_updated_on',
        '<',
        startNextMonth
    );

    resolvedGA.addAggregate('COUNT');
    resolvedGA.query();


    if (resolvedGA.next()) {

        data.resolvedThisMonth =
            parseInt(
                resolvedGA.getAggregate('COUNT'),
                10
            ) || 0;
    }



    // ----------------------------------
    // 9. RECENT HR CASES
    // ----------------------------------

    var caseGR =
        new GlideRecord(
            'x_snc_unified_hr_0_hr_case'
        );

    applyCaseFilter(caseGR);

    caseGR.orderByDesc('created_on');
    caseGR.setLimit(5);
    caseGR.query();


    while (caseGR.next()) {

    var statusValue =
        caseGR.getValue('status');

    var statusLabel =
        caseGR.getDisplayValue('status');

    if (
        statusValue ==
        'awaiting_employee_confirmation'
    ) {

        statusLabel =
            'Awaiting Employee Confirmation';
    }


    var createdOn =
        caseGR.getDisplayValue(
            'created_on'
        );

    if (!createdOn) {

        createdOn =
            caseGR.getDisplayValue(
                'sys_created_on'
            );
    }


    data.recentHRCases.push({

        sys_id:
            caseGR.getUniqueValue(),

        number:
            caseGR.getDisplayValue(
                'number'
            ),

        requested_by:
            caseGR.getDisplayValue(
                'request_by'
            ),

        category:
            caseGR.getDisplayValue(
                'category'
            ),

        priority:
            caseGR.getDisplayValue(
                'priority'
            ),

        assignment_group:
            caseGR.getDisplayValue(
                'assignment_group'
            ),

        assigned_to:
            caseGR.getDisplayValue(
                'assigned_to'
            ),

        status:
            statusLabel,

        status_value:
            statusValue,

        created_on:
            createdOn

    });
}



    // ----------------------------------
    // 10. RECENT LEAVE REQUESTS
    // Manager + Leave Agent only
    // ----------------------------------

    if (data.isHRManager || data.isLeaveAgent) {

        var leaveGR =
            new GlideRecord(
                'x_snc_unified_hr_0_leave_request'
            );

        leaveGR.addQuery(
            'status',
            'pending_hr'
        );

        leaveGR.orderByDesc('applied_on');
        leaveGR.setLimit(5);
        leaveGR.query();


        while (leaveGR.next()) {

            data.recentLeaveRequests.push({

                sys_id:
                    leaveGR.getUniqueValue(),

                number:
                    leaveGR.getDisplayValue('number'),

                employee:
                    leaveGR.getDisplayValue(
                        'requested_by'
                    ),

                leave_type:
                    leaveGR.getDisplayValue(
                        'leave_type'
                    ),

                start_date:
                    leaveGR.getDisplayValue(
                        'start_date'
                    ),

                end_date:
                    leaveGR.getDisplayValue(
                        'end_date'
                    ),

                days:
                    leaveGR.getDisplayValue(
                        'number_of_leave_days'
                    ),

                status:
                    leaveGR.getDisplayValue('status')
            });
        }
    }

	data.leavesThisMonth = 0;

	var leaveMonthGR = new GlideAggregate(
		'x_snc_unified_hr_0_leave_request'
	);

	leaveMonthGR.addQuery('status', 'approved');

	leaveMonthGR.addQuery(
		'start_date',
		'>=',
		gs.beginningOfThisMonth()
	);

	leaveMonthGR.addQuery(
		'start_date',
		'<=',
		gs.endOfThisMonth()
	);

	leaveMonthGR.addAggregate('COUNT');
	leaveMonthGR.query();

	if (leaveMonthGR.next()) {
		data.leavesThisMonth =
			parseInt(
				leaveMonthGR.getAggregate('COUNT'),
				10
			) || 0;
	}

	data.leaveAnalytics = {
		pendingHOD: 0,
		pendingHR: 0,
		approved: 0,
		rejected: 0,
		cancelled: 0,
		total: 0
	};

	data.caseAnalytics = {
		open: 0,
		inProgress: 0,
		resolved: 0,
		closed: 0,
		total: 0
	};

	data.categoryAnalytics = [];

	var leaveAnalyticsGR =
		new GlideRecord(
			'x_snc_unified_hr_0_leave_request'
		);

	leaveAnalyticsGR.query();

	while (leaveAnalyticsGR.next()) {

		var leaveStatus =
			leaveAnalyticsGR.getValue('status');

		data.leaveAnalytics.total++;

		if (leaveStatus == 'pending_hod') {
			data.leaveAnalytics.pendingHOD++;
		}

		if (leaveStatus == 'pending_hr') {
			data.leaveAnalytics.pendingHR++;
		}

		if (leaveStatus == 'approved') {
			data.leaveAnalytics.approved++;
		}

		if (leaveStatus == 'rejected') {
			data.leaveAnalytics.rejected++;
		}

		if (leaveStatus == 'cancelled') {
			data.leaveAnalytics.cancelled++;
		}
	}

	var caseAnalyticsGR =
		new GlideRecord(
			'x_snc_unified_hr_0_hr_case'
		);

	caseAnalyticsGR.query();

	while (caseAnalyticsGR.next()) {

		var caseStatus =
			caseAnalyticsGR.getValue('status');

		data.caseAnalytics.total++;

		if (caseStatus == 'open') {
			data.caseAnalytics.open++;
		}

		if (caseStatus == 'in_progress') {
			data.caseAnalytics.inProgress++;
		}

		if (caseStatus == 'resolved') {
			data.caseAnalytics.resolved++;
		}

		if (caseStatus == 'closed') {
			data.caseAnalytics.closed++;
		}
	}

	function buildGradient(values, colors) {

		var total = 0;

		for (var i = 0; i < values.length; i++) {
			total += values[i];
		}

		if (total == 0) {
			return '#e9edf3';
		}

		var current = 0;
		var parts = [];

		for (var j = 0; j < values.length; j++) {

			if (values[j] == 0) {
				continue;
			}

			var start =
				(current / total) * 100;

			current += values[j];

			var end =
				(current / total) * 100;

			parts.push(
				colors[j] +
				' ' + start + '% ' +
				end + '%'
			);
		}

		return 'conic-gradient(' +
			parts.join(',') +
			')';
	}

	data.leaveDonutGradient =
		buildGradient(
			[
				data.leaveAnalytics.pendingHOD,
				data.leaveAnalytics.pendingHR,
				data.leaveAnalytics.approved,
				data.leaveAnalytics.rejected,
				data.leaveAnalytics.cancelled
			],
			[
				'#f59e0b',
				'#3b82f6',
				'#22c55e',
				'#ef4444',
				'#a855f7'
			]
		);


	data.caseDonutGradient =
		buildGradient(
			[
				data.caseAnalytics.open,
				data.caseAnalytics.inProgress,
				data.caseAnalytics.resolved,
				data.caseAnalytics.closed
			],
			[
				'#f59e0b',
				'#3b82f6',
				'#22c55e',
				'#6b7280'
			]
		);


	var categoryMap = {};

	var categoryGR =
		new GlideRecord(
			'x_snc_unified_hr_0_hr_case'
		);

	categoryGR.addQuery(
		'status',
		'IN',
		'open,in_progress'
	);

	categoryGR.query();

	while (categoryGR.next()) {

		var category =
			categoryGR.getDisplayValue('category');

		if (!category) {
			category = 'General';
		}

		if (!categoryMap[category]) {
			categoryMap[category] = 0;
		}

		categoryMap[category]++;
	}


	var maxCategoryCount = 0;

	for (var categoryName in categoryMap) {

		if (categoryMap[categoryName] >
			maxCategoryCount) {

			maxCategoryCount =
				categoryMap[categoryName];
		}
	}


	for (var name in categoryMap) {

		var count =
			categoryMap[name];

		var percentage =
			maxCategoryCount > 0
			? Math.round(
				(count / maxCategoryCount) * 100
			)
			: 0;

		data.categoryAnalytics.push({

			name: name,

			count: count,

			percentage: percentage

		});
	}


	data.categoryAnalytics.sort(
		function(a, b) {
			return b.count - a.count;
		}
	);

	// ----------------------------------
	// 11. EXECUTIVE HR INSIGHTS
	// HR MANAGER ONLY
	// ----------------------------------

	data.executiveInsights = {

		// Leave intelligence
		leaveTrend: [],
		totalLeaveRequests: 0,
		peakLeaveMonth: "",
		peakLeaveCount: 0,

		// HR case intelligence
		caseTrend: [],
		totalCasesSixMonths: 0,
		peakCaseMonth: "",
		peakCaseCount: 0,

		topCaseCategory: "",
		topCaseCategoryCount: 0,

		caseTrendDirection: "Stable",
		recentCaseVolume: 0,
		previousCaseVolume: 0
	};

	if (data.isHRManager) {


		// ==========================================================
		// SEASONAL LEAVE DEMAND - LAST 6 MONTHS
		// ==========================================================

		var leaveToday =
			new GlideDateTime();

		var leaveMonthNames = [
			"Jan",
			"Feb",
			"Mar",
			"Apr",
			"May",
			"Jun",
			"Jul",
			"Aug",
			"Sep",
			"Oct",
			"Nov",
			"Dec"
		];

		var monthlyLeaveMap = {};


		// ----------------------------------
		// CREATE LAST 6 MONTH BUCKETS
		// ----------------------------------

		for (var lm = 5; lm >= 0; lm--) {

			var leaveMonthDate =
				new GlideDateTime(
					leaveToday
				);

			leaveMonthDate.addMonthsUTC(
				-lm
			);

			var leaveMonthNumber =
				leaveMonthDate.getMonthUTC();

			var leaveMonthYear =
				leaveMonthDate.getYearUTC();

			var leaveMonthKey =
				leaveMonthYear +
				"-" +
				leaveMonthNumber;


			monthlyLeaveMap[
				leaveMonthKey
			] = {

				label:
					leaveMonthNames[
						leaveMonthNumber - 1
					],

				year:
					leaveMonthYear,

				count:
					0
			};
		}


		// ----------------------------------
		// READ LEAVE REQUESTS
		// ----------------------------------

		var leaveTrendGR =
			new GlideRecord(
				'x_snc_unified_hr_0_leave_request'
			);

		leaveTrendGR.addNotNullQuery(
			'applied_on'
		);

		leaveTrendGR.query();


		while (leaveTrendGR.next()) {

			var appliedOnValue =
				leaveTrendGR.getValue(
					'applied_on'
				);


			if (!appliedOnValue) {
				continue;
			}


			var appliedOnGdt =
				new GlideDateTime(
					appliedOnValue
				);


			var appliedMonth =
				appliedOnGdt.getMonthUTC();

			var appliedYear =
				appliedOnGdt.getYearUTC();


			var appliedKey =
				appliedYear +
				"-" +
				appliedMonth;


			// Only count records belonging
			// to our last-6-month buckets
			if (
				monthlyLeaveMap[
					appliedKey
				]
			) {

				monthlyLeaveMap[
					appliedKey
				].count++;

				data.executiveInsights
					.totalLeaveRequests++;
			}
		}


		// ----------------------------------
		// BUILD LEAVE TREND ARRAY
		// ----------------------------------

		for (var lx = 5; lx >= 0; lx--) {

			var leaveOutputDate =
				new GlideDateTime(
					leaveToday
				);

			leaveOutputDate.addMonthsUTC(
				-lx
			);


			var leaveOutputMonth =
				leaveOutputDate.getMonthUTC();

			var leaveOutputYear =
				leaveOutputDate.getYearUTC();


			var leaveOutputKey =
				leaveOutputYear +
				"-" +
				leaveOutputMonth;


			var leaveTrendItem =
				monthlyLeaveMap[
					leaveOutputKey
				];


			if (leaveTrendItem) {

				data.executiveInsights
					.leaveTrend
					.push(
						leaveTrendItem
					);


				// Find peak month
				if (
					leaveTrendItem.count >
					data.executiveInsights
						.peakLeaveCount
				) {

					data.executiveInsights
						.peakLeaveCount =
							leaveTrendItem.count;

					data.executiveInsights
						.peakLeaveMonth =
							leaveTrendItem.label;
				}
			}
		}

		// ----------------------------------
		// HR CASE TREND - LAST 6 MONTHS
		// ----------------------------------

		var caseToday = new GlideDateTime();
		var caseMonthNames = [
			"Jan",
			"Feb",
			"Mar",
			"Apr",
			"May",
			"Jun",
			"Jul",
			"Aug",
			"Sep",
			"Oct",
			"Nov",
			"Dec"
		];
		var monthlyCaseMap = {};


		// Create last 6 months
		for (var cm = 5; cm >= 0; cm--) {

			var caseMonthDate =
				new GlideDateTime(caseToday);

			caseMonthDate.addMonthsUTC(-cm);

			var caseMonthNumber =
				caseMonthDate.getMonthUTC();

			var caseMonthYear =
				caseMonthDate.getYearUTC();

			var caseMonthKey =
				caseMonthYear + "-" + caseMonthNumber;

			monthlyCaseMap[caseMonthKey] = {

				label:
					caseMonthNames[
						caseMonthNumber - 1
					],

				year:
					caseMonthYear,

				count:
					0
			};
		}


		// ----------------------------------
		// START DATE FOR CASE TREND
		// ----------------------------------

		var sixMonthsAgoCases =
			new GlideDateTime(caseToday);

		sixMonthsAgoCases.addMonthsUTC(-5);

		sixMonthsAgoCases.setDayOfMonthUTC(1);


		// ----------------------------------
		// GET HR CASES
		// ----------------------------------

		var caseTrendGR =
			new GlideRecord(
				'x_snc_unified_hr_0_hr_case'
			);

		caseTrendGR.query();


		var categoryTrendMap = {};


		while (caseTrendGR.next()) {

			// Prefer custom Created On field
			var caseCreatedValue =
				caseTrendGR.getValue(
					'created_on'
				);


			// Fall back to system Created date
			if (!caseCreatedValue) {

				caseCreatedValue =
					caseTrendGR.getValue(
						'sys_created_on'
					);
			}


			if (!caseCreatedValue) {
				continue;
			}


			var caseCreatedGdt =
				new GlideDateTime(
					caseCreatedValue
				);


			// Ignore cases older than 6-month window
			if (
				caseCreatedGdt.compareTo(
					sixMonthsAgoCases
				) < 0
			) {
				continue;
			}


			var caseCreatedMonth =
				caseCreatedGdt.getMonthUTC();

			var caseCreatedYear =
				caseCreatedGdt.getYearUTC();

			var caseCreatedKey =
				caseCreatedYear +
				"-" +
				caseCreatedMonth;


			if (
				monthlyCaseMap[
					caseCreatedKey
				]
			) {

				monthlyCaseMap[
					caseCreatedKey
				].count++;

				data.executiveInsights
					.totalCasesSixMonths++;
			}


			// ----------------------------------
			// CASE CATEGORY ANALYSIS
			// ----------------------------------

			var trendCategory =
				caseTrendGR.getDisplayValue(
					'category'
				);


			if (!trendCategory) {
				trendCategory = "General";
			}


			if (
				!categoryTrendMap[
					trendCategory
				]
			) {

				categoryTrendMap[
					trendCategory
				] = 0;
			}


			categoryTrendMap[
				trendCategory
			]++;
		}


		// ----------------------------------
		// BUILD CASE TREND ARRAY
		// ----------------------------------

		for (var cx = 5; cx >= 0; cx--) {

			var caseOutputDate =
				new GlideDateTime(caseToday);

			caseOutputDate.addMonthsUTC(-cx);

			var caseOutputMonth =
				caseOutputDate.getMonthUTC();

			var caseOutputYear =
				caseOutputDate.getYearUTC();

			var caseOutputKey =
				caseOutputYear +
				"-" +
				caseOutputMonth;


			var caseTrendItem =
				monthlyCaseMap[
					caseOutputKey
				];


			if (caseTrendItem) {

				data.executiveInsights
					.caseTrend
					.push(
						caseTrendItem
					);


				if (
					caseTrendItem.count >
					data.executiveInsights
						.peakCaseCount
				) {

					data.executiveInsights
						.peakCaseCount =
						caseTrendItem.count;

					data.executiveInsights
						.peakCaseMonth =
						caseTrendItem.label;
				}
			}
		}


		// ----------------------------------
		// TOP CASE CATEGORY
		// ----------------------------------

		for (
			var caseCategoryName
			in categoryTrendMap
		) {

			var caseCategoryCount =
				categoryTrendMap[
					caseCategoryName
				];


			if (
				caseCategoryCount >
				data.executiveInsights
					.topCaseCategoryCount
			) {

				data.executiveInsights
					.topCaseCategoryCount =
						caseCategoryCount;

				data.executiveInsights
					.topCaseCategory =
						caseCategoryName;
			}
		}


		// ----------------------------------
		// CASE TREND DIRECTION
		//
		// Previous 3 months vs latest 3 months
		// ----------------------------------

		var caseTrendLength =
			data.executiveInsights
				.caseTrend.length;


		if (caseTrendLength >= 6) {

			var previousVolume = 0;
			var recentVolume = 0;


			for (
				var trendIndex = 0;
				trendIndex < 3;
				trendIndex++
			) {

				previousVolume +=
					data.executiveInsights
						.caseTrend[
							trendIndex
						].count;
			}


			for (
				var recentIndex = 3;
				recentIndex < 6;
				recentIndex++
			) {

				recentVolume +=
					data.executiveInsights
						.caseTrend[
							recentIndex
						].count;
			}


			data.executiveInsights
				.previousCaseVolume =
					previousVolume;


			data.executiveInsights
				.recentCaseVolume =
					recentVolume;


			if (
				recentVolume >
				previousVolume
			) {

				data.executiveInsights
					.caseTrendDirection =
						"Increasing";

			} else if (
				recentVolume <
				previousVolume
			) {

				data.executiveInsights
					.caseTrendDirection =
						"Decreasing";

			} else {

				data.executiveInsights
					.caseTrendDirection =
						"Stable";
			}
		}
	}

})();
